/**
 * [B20 B2] D20-35: the three route matrices that were regenerated by convention only are now byte-pinned to pure renderers
 * the generators export (written only when a generator runs as a script), and the /api/mcp rows state its contract:
 * authenticated, load-bearing through mcpBearerJsonRoute, a 65 536-byte / 10 000 ms bounded body read after authorization.
 */
import { readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it, vi } from "vitest";
import { renderMethodAuthorizationMatrix, renderRequestBodyBoundaryMatrix } from "../../../../scripts/generate-b16-0-4-artifacts";
import { renderRouteWrapperMatrix } from "../../../../scripts/generate-b16-0-7-artifacts";

const ROOT = process.cwd();
const METHOD_MATRIX = join(ROOT, "artifacts", "ai-control-plane-b16-0-4", "method-authorization-matrix.csv");
const BODY_MATRIX = join(ROOT, "artifacts", "ai-control-plane-b16-0-4", "request-body-boundary-matrix.csv");
const WRAPPER_MATRIX = join(ROOT, "artifacts", "ai-control-plane-b16-0-7", "route-wrapper-matrix.csv");
const committed = (file: string): string => readFileSync(file, "utf8").replaceAll("\r\n", "\n");
const rowsFor = (csv: string, route: string): string[] => csv.split("\n").filter((line) => line.split(",")[1] === route);

describe("[B20 B2] D — the route matrices are byte-pinned", () => {
  it("1. method-authorization-matrix.csv equals its renderer", () => {
    expect(committed(METHOD_MATRIX)).toBe(renderMethodAuthorizationMatrix(ROOT));
  }, 180_000);

  it("2. request-body-boundary-matrix.csv equals its renderer", () => {
    expect(committed(BODY_MATRIX)).toBe(renderRequestBodyBoundaryMatrix(ROOT));
  }, 180_000);

  it("3. route-wrapper-matrix.csv equals its renderer", () => {
    expect(committed(WRAPPER_MATRIX)).toBe(renderRouteWrapperMatrix(ROOT));
  }, 180_000);

  it("4. the /api/mcp rows: authenticated, load-bearing through mcpBearerJsonRoute, 65536 bytes / 10000 ms, authorize-then-body; canonical-wrapper, auth", () => {
    expect(rowsFor(committed(METHOD_MATRIX), "/api/mcp")).toEqual(["POST,/api/mcp,auth,authenticated,mcpBearerJsonRoute(…),load-bearing,wrapper,mcpBearerJsonRoute"]);
    const body = rowsFor(committed(BODY_MATRIX), "/api/mcp");
    expect(body).toHaveLength(1);
    expect(body[0]!.split(",").slice(0, 10)).toEqual(["POST", "/api/mcp", "auth", "authenticated", "mcpBearerJsonRoute(…)", "application/json", "65536", "10000", "authorize-then-body", "canonical-wrapper:mcpBearerJsonRoute"]);
    expect(rowsFor(committed(WRAPPER_MATRIX), "/api/mcp")).toEqual(["POST,/api/mcp,auth,canonical-wrapper,mcpBearerJsonRoute,(adopted),adopted"]);
    expect(rowsFor(committed(WRAPPER_MATRIX), "/api/mcp/token")).toEqual(["POST,/api/mcp/token,auth+csrf,canonical-wrapper,authenticatedJsonRoute,(adopted),adopted"]);
    expect(rowsFor(committed(WRAPPER_MATRIX), "/.well-known/oauth-protected-resource/api/mcp")).toEqual(["GET,/.well-known/oauth-protected-resource/api/mcp,public,canonical-wrapper,publicRoute,(adopted),adopted"]);
  });

  it("5. importing the generators writes nothing (they write only when run as a script)", async () => {
    const before = [METHOD_MATRIX, BODY_MATRIX, WRAPPER_MATRIX].map((file) => [statSync(file).mtimeMs, committed(file)] as const);
    vi.resetModules();
    await import("../../../../scripts/generate-b16-0-4-artifacts");
    await import("../../../../scripts/generate-b16-0-7-artifacts");
    const after = [METHOD_MATRIX, BODY_MATRIX, WRAPPER_MATRIX].map((file) => [statSync(file).mtimeMs, committed(file)] as const);
    expect(after).toEqual(before);
    for (const script of ["generate-b16-0-4-artifacts.ts", "generate-b16-0-7-artifacts.ts"]) {
      expect(readFileSync(join(ROOT, "scripts", script), "utf8"), script).toMatch(/const invokedAsScript = /);
    }
  }, 180_000);
});
